import { Action, ActionPanel, Color, Icon, List, showHUD, showToast, Toast } from "@raycast/api";
import { exec } from "child_process";
import { useEffect, useState } from "react";
import { promisify } from "util";

const execPromise = promisify(exec);
const CTL_BIN = "/opt/homebrew/bin/omniwmctl";

interface WindowItem {
  id: string;
  title: string;
  app: {
    name: string;
    bundleId: string;
  };
}

export default function Command() {
  const [windows, setWindows] = useState<WindowItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);

  useEffect(() => {
    async function fetchWindows() {
      try {
        const { stdout } = await execPromise(`${CTL_BIN} query windows --json`);
        const response = JSON.parse(stdout);
        const list = response?.result?.payload?.windows || [];
        setWindows(list);
      } catch (error: any) {
        showToast({
          style: Toast.Style.Failure,
          title: "Failed to load windows",
          message: error.message,
        });
      } finally {
        setLoading(false);
      }
    }
    fetchWindows();
  }, []);

  async function focusWindow(windowId: string) {
    try {
      await execPromise(`${CTL_BIN} window focus ${windowId}`);
      await showHUD("Focused Window");
    } catch (error: any) {
      showToast({
        style: Toast.Style.Failure,
        title: "Failed to focus window",
        message: error.message,
      });
    }
  }

  return (
    <List isLoading={loading} searchBarPlaceholder="Search active windows...">
      <List.Section title="Managed Windows">
        {windows.map((win) => (
          <List.Item
            key={win.id}
            title={win.app?.name || "Unknown App"}
            subtitle={win.title || "Untitled Window"}
            icon={{ source: Icon.Window, tintColor: Color.Orange }}
            actions={
              <ActionPanel>
                <Action title="Focus Window" onAction={() => focusWindow(win.id)} />
              </ActionPanel>
            }
          />
        ))}
      </List.Section>
    </List>
  );
}
